contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 shareAmount) public {
        address to = address(0xBEEF);
        uint256 baseMinAmount = 0;
        uint256 quoteMinAmount = 0;
        bytes memory data = new bytes(0);
        uint256 deadline = type(uint256).max;

        uint256 beforeTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 beforeCallerShares = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        require(shareAmount <= beforeCallerShares, "precondition");

        c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline); if (__ESBMC_reverted()) return;

        uint256 afterTotalSupply = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 afterCallerShares = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(afterTotalSupply == beforeTotalSupply - shareAmount && afterCallerShares == beforeCallerShares - shareAmount);
    }
}

