        uint256 quoteMinAmount = 0;
        bytes memory data = new bytes(0);
        uint256 deadline = type(uint256).max;
        uint256 beforeTotalSupply;
        try c.totalSupply() returns (uint256 __r) { beforeTotalSupply = __r; } catch { return; }
        uint256 beforeCallerShares;
        try c.balanceOf(address(this)) returns (uint256 __r) { beforeCallerShares = __r; } catch { return; }
        vm.assume(shareAmount <= beforeCallerShares);
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, deadline) {} catch { return; }
        uint256 afterTotalSupply;
        try c.totalSupply() returns (uint256 __r) { afterTotalSupply = __r; } catch { return; }
